    case 180:
        if (!st.hasDocMesh || st.bodyBBoxCache.empty()) return;
        s.otherBounds = st.bodyBBoxCache;
        s.otherDatums = st.docMirror.refDatums();
        if (s.expectUnavailable) { advance(23); return; }
